mapper.sql:
WHERE h.deleted_yn = 'N'
AND h.progress_status = #{progressStatus}
AND ( UPPER(h.sales_order_no) LIKE '%' || UPPER(#{keyword}) || '%' OR TO_CHAR(h.business_date, 'YYYY/MM/DD') LIKE '%' || #{keyword} || '%' OR UPPER(h.partner_name) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(h.assignee_name) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(h.warehouse_name) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(h.note) LIKE '%' || UPPER(#{keyword}) || '%' OR EXISTS ( SELECT 1 FROM SALES_ORDER_LINE search_line LEFT JOIN ITEM search_item ON search_item.item_id = search_line.item_id WHERE search_line.sales_order_id = h.sales_order_id AND search_line.deleted_yn = 'N' AND ( UPPER(search_item.item_code) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(search_line.item_name) LIKE '%' || UPPER(#{keyword}) || '%' ) ) )

mapper.insert:

	SELECT seq_sales_order_line.NEXTVAL FROM DUAL


INSERT INTO SALES_ORDER_LINE (
sales_order_line_id, sales_order_id, quotation_line_id,
item_id, item_name, specification, unit, quantity,
unit_price, supply_amount, vat_amount, total_amount, note
) VALUES (
#{salesOrderLineId}, #{salesOrderId}, #{quotationLineId},
#{itemId}, #{itemName}, #{specification}, #{unit}, #{quantity},
#{unitPrice}, #{supplyAmount}, #{vatAmount}, #{totalAmount}, #{note}
)
